 std::string script;if(!scriptPath.empty())script=read(scriptPath);else{std::ostringstream s;s<<std::setprecision(17)<<"# Deterministic bench: physical force/sphere, then explicit fixture release.\n";s<<"force 30 150 "<<target<<" 0.015 0 0\n";V3 c=lab.patches[0].sample({.5,.5});s<<"sphere 180 360 "<<c.x+.7<<' '<<c.y<<' '<<c.z<<' '<<c.x-.7<<' '<<c.y<<' '<<c.z<<" .22\n";s<<"pull 380 640 "<<target<<" 2 0 0\n";for(auto e:g.edges)if(g.particles[e.a].anchor>=0||g.particles[e.b].anchor>=0)s<<"cut 720 "<<e.id<<'\n';script=s.str();}
